// Reference solution
function eui64(mac) {
  var b = mac.split(/[:-]/).map(function (x) { return parseInt(x, 16); });
  b[0] = b[0] ^ 2;
  var r = [b[0], b[1], b[2], 0xff, 0xfe, b[3], b[4], b[5]], g = [];
  for (var i = 0; i < 8; i += 2) g.push((r[i] * 256 + r[i + 1]).toString(16));
  return g.join(':');
}
